scwin.vScrenID = "ULDINS15600.xml";
scwin.cnt = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 예탁증서 표준코드관리  목록 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    if ((txb_pSTD_CD.getValue() == "" || txb_pSTD_CD.getValue().indexOf(" ") == "") &&
        (txb_pISU_NM.getValue() == "" || txb_pISU_NM.getValue().indexOf(" ") == "") &&
        (txb_pISUR_CD.getValue() == "" || txb_pISUR_CD.getValue().indexOf(" ") == "") &&
        (edt_pSTD_CD_GRNT_DD_SDATE.getValue() == "" || edt_pSTD_CD_GRNT_DD_SDATE.text.indexOf(" ") == "") &&
        (edt_pSTD_CD_GRNT_DD_EDATE.getValue() == "" || edt_pSTD_CD_GRNT_DD_EDATE.text.indexOf(" ") == "")) {
        $c.win.alert("조회 파라메터가 부족합니다");
        return;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_pISU_DD_SDATE, edt_pISU_DD_EDATE) == false) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE) == false) {
        return false;
    }

    //데이터셋 초기화
    dts_List.removeAll();
    dts_detail.removeAll();
    $c.stf.setObjectValue(cmb_SECU_KIND_CD, "");

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS15600_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listStdCdDrInfoInquiry" + "&{P}STD_CD=" + txb_pSTD_CD.getValue() + "&{P}ISU_NM=" + txb_pISU_NM.getValue() + "&{P}ISUR_CD=" + txb_pISUR_CD.getValue() + "&{P}ISU_DD_SDATE=" + edt_pISU_DD_SDATE.getValue() + "&{P}ISU_DD_EDATE=" + edt_pISU_DD_EDATE.getValue() + "&{P}STD_CD_GRNT_DD_SDATE=" + edt_pSTD_CD_GRNT_DD_SDATE.getValue() + "&{P}STD_CD_GRNT_DD_EDATE=" + edt_pSTD_CD_GRNT_DD_EDATE.getValue();
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};


/********************************************** 
 * 함수명   : ins_detail
 * 설명       : 예탁증서 표준코드관리 상세 조회한다.
 ***********************************************/
scwin.ins_detail = function(STD_CD) {
    //데이터셋 초기화
    dts_detail.removeAll();

    // 예탁증서 표준코드관리
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS15600_VIEW_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.readStdCdDrInfoView" + "&{P}STD_CD=" + STD_CD;
    dts_detail.DataID = encodeURI(url);
    dts_detail.reset();
};



/********************************************** 
 * 함수명   : ins_modify	
 * 설명       : 예탁증서 표준코드관리 저장 , 수정 한다. screenProcsTpCd 02,03
 ***********************************************/
scwin.ins_modify = function(mflag) {
    var screenProcsTpCd = "03";
    if (screenProcsTpCd == '03') {
        // 수정

        if (!$c.cp.isModified(dts_detail)) {
            $c.win.alert("변경된 데이터가 없습니다.");
            return;
        }
        if (txb_STD_CD.getValue() == "" || txb_STD_CD.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "표준코드"));
            txb_STD_CD.focus();
            return;
        }
        if (!$c.stf.checkMaxLength(txb_STD_CD, 12, "표준코드")) {
            txb_STD_CD.focus();
            return false;
        }
        if (txb_ISU_NM.getValue() == "" || txb_ISU_NM.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목명"));
            txb_ISU_NM.focus();
            return false;
        }
        if (txb_ISU_ABBRV.getValue() == "" || txb_ISU_ABBRV.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목약명"));
            txb_ISU_ABBRV.focus();
            return false;
        }
        if (txb_ISU_ENG_NM.getValue() == "" || txb_ISU_ENG_NM.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (txb_ISU_ENG_ABBRV.getValue() == "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_NM, 80, "한글종목명")) {
            txb_ISU_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ABBRV, 40, "한글종목약명")) {
            txb_ISU_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) {
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) {
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txa_NUSUAL_ISU_COND_CONTN, 60, "특이발행조건")) {
            //txb_ISU_ENG_ABBRV.value = "";
            txa_NUSUAL_ISU_COND_CONTN.focus();
            return false;
        }
        if (mflag == "N") return;
        trs_Save.Action = "/StdCdDrInfoAction.do?method=modifyStdCdDrInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + screenProcsTpCd;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_detail)";
        trs_Save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
        trs_Save.Post();
    }
};




/********************************************** 
 * 함수명   : ins_remove	
 * 설명       : 표준코드 삭제
 ***********************************************/
scwin.ins_remove = function() {
    var screenProcsTpCd = "04";
    //dts_Delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Delete.insertRow();
    dts_Delete.setCellData(1, "STD_CD", dts_detail.getCellData(dts_detail.getRowPosition(), "STD_CD"));
    dts_Delete.setCellData(1, "ISU_NM", dts_detail.getCellData(dts_detail.getRowPosition(), "ISU_NM"));
    dts_Delete.setCellData(1, "CHG_RSN", txb_DEL_RSN.getValue());
    trs_Delete.Action = "/StdCdDrInfoAction.do?method=removeStdCdDrInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + screenProcsTpCd;
    trs_Delete.KeyName = "toinb_dataid4";
    trs_Delete.KeyValue = "JSP(I:pInput=dts_Delete)";
    trs_Delete.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
    trs_Delete.Post();
};



/********************************************** 
 * 함수명   : Change_cfi
 * 설명       : 보통주의 cfi 변경 설정하기...
 ***********************************************/
scwin.Change_cfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    var cfi = "EMXXX";
    var secu_kind_cd = $c.stf.getObjectValue(cmb_SECU_KIND_CD);
    if (secu_kind_cd == "") {
        cfi += "_";
    } else {
        cfi += secu_kind_cd;
    }
    $c.stf.setObjectValue(txb_CFI_CD, cfi);
};



/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달값을 정의한다.
 ***********************************************/
scwin.arrPar = new Array();
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 표준코드 OR 발행기관 코드      
    scwin.arrPar[1] = txb_param2.getValue();

    //alert(arrPar[0] + " " + arrPar[1]);
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : ins_createStdCdStkInfoStdIsuNm
 * 설명       : 주권 종목명 생성
 ***********************************************/
scwin.ins_createStdCdStkInfoStdIsuNm = function() {
    dts_createStdCdStkInfoStdIsuNm.removeAll();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=STDCDTEMP_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.createStdCdStkInfoStdIsuNm2" + "&{P}STKCERT_KIND_NM=000" + "&{P}ISUR_CD=" + txb_ISUR_CD.getValue();

    //alert(url); //return;
    dts_createStdCdStkInfoStdIsuNm.DataID = encodeURI(url);
    dts_createStdCdStkInfoStdIsuNm.reset();
};



/********************************************** 
 * 함수명   : fn_Change_cfi
 * 설명       : cfi 변경 설정
 ***********************************************/
scwin.fn_Change_cfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    var cfi = "";
    var str_cfi = dts_detail.getCellData(dts_detail.getRowPosition(), "CFI_CD");
    var temp = $c.stf.getObjectValue(cmb_cb_p_group); //선택된그룹

    //카테고리셋팅
    if (temp == "") {
        cfi = "_";
    } else if (temp == "E") {
        cfi = "E";
    } else if (temp == "D") {
        cfi = "D";
    } else if (temp == "R") {
        cfi = "R";
    }

    //그룹
    if ($c.stf.getObjectValue(cmb_cb_p_group) == "") cfi += "_";

    else cfi += "D"; //cfi += getObjectValue(cmb_cb_p_group);

    //1차속성
    if ($c.stf.getObjectValue(cmb_cb_p_attr_1) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_1);

    //2차속성
    if ($c.stf.getObjectValue(cmb_cb_p_attr_2) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_2);

    //3차속성
    if ($c.stf.getObjectValue(cmb_cb_p_attr_3) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_3);

    //4차속성
    if ($c.stf.getObjectValue(cmb_cb_p_attr_4) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_4);
    txb_CFI_CD.setValue(cfi); // cfi 설정

};


/********************************************** 
 * 함수명   : fn_set_Change
 * 설명       :  상세 조회시 CFI 상세 설정 
 ***********************************************/
scwin.fn_set_Change = function(str_cfi) {
    if (str_cfi == "") return;
    ins_cfi_set(dts_cfi_group, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "06", "E", "", "", "G");
    ins_cfi_set(dts_cfi_group_1, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "06", "D", "", "", "G");
    ins_cfi_set(dts_cfi_group_2, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "06", "R", "", "", "G");

    //하나의 데이터셋으로 합치기
    for (var i = 2; i < dts_cfi_group_1.getTotalRow() + 1; i++) {
        dts_cfi_group.insertRow();
        dts_cfi_group.setCellData(dts_cfi_group.getTotalRow(), "VALUE", dts_cfi_group_1.getCellData(i, "VALUE"));
        dts_cfi_group.setCellData(dts_cfi_group.getTotalRow(), "TEXT", dts_cfi_group_1.getCellData(i, "TEXT"));
    }
    for (var i = 2; i < dts_cfi_group_2.getTotalRow() + 1; i++) {
        dts_cfi_group.insertRow();
        dts_cfi_group.setCellData(dts_cfi_group.getTotalRow(), "VALUE", dts_cfi_group_2.getCellData(i, "VALUE"));
        dts_cfi_group.setCellData(dts_cfi_group.getTotalRow(), "TEXT", dts_cfi_group_2.getCellData(i, "TEXT"));
    }

    //DR 특수케이스
    var temp = str_cfi.substring(0, 2); //카테고리 + 그룹
    //alert(temp);
    if (temp == "ED") {
        $c.stf.setObjectValue(cmb_cb_p_group, "E");
    } else if (temp == "DD") {
        $c.stf.setObjectValue(cmb_cb_p_group, "D");
    } else if (temp == "RD") {
        $c.stf.setObjectValue(cmb_cb_p_group, "R");
    }
    //setObjectValue(cmb_cb_p_group,str_cfi.substring(1, 2));
    $c.stf.setObjectValue(cmb_cb_p_attr_1, str_cfi.substring(2, 3));
    $c.stf.setObjectValue(cmb_cb_p_attr_2, str_cfi.substring(3, 4));
    $c.stf.setObjectValue(cmb_cb_p_attr_3, str_cfi.substring(4, 5));
    $c.stf.setObjectValue(cmb_cb_p_attr_4, str_cfi.substring(5, 6));
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    //PanelToGroupBox(panel_3);
    txb_pSTD_CD.setValue("KR8");
    ins_combo_set(dts_STD_CD_APCT_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03527"); //03527 - 신청자구분 

    /*
    cmb_PREFSTK_YN <- 보통주/우선주 ->  도메인 미존재 하드코딩으로 콤보로 만든다.
    */
    ins_combo_set(dts_CNTR_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "01371", "SEL");
    ins_combo_set(dts_NEWSTK_KIND_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03428", "SEL");
    ins_combo_set(dts_BAS_SECU_KIND_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03426", "SEL");
    ins_combo_set(dts_DOM_FORN_ISU_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03407", "SEL");
    ins_combo_set(dts_CURR_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "02475", "SEL");
    ins_combo_set(dts_LIST_STAT_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "00714", "SEL"); //00714 - D:상장폐지I:미발행N:비상장Y:상장Z:기타 
    fn_CtrlBtn_temp("no_data");

    //hidden패널
    $c.stf.showObj(panel_12, false);
    var arrObjectApct = [txb_APCT_NM, txb_APCT_FAX_NO, txb_APCT_TEL_NO, txb_APCT_INNR_NO];
    for (var i = 0; i < arrObjectApct.length; i++) {
        fn_apct_delchar(arrObjectApct[i]);
    }
    txb_pSTD_CD.focus();
};
scwin.btn_file_onclick = function() {
    /*
    txb_param1 에는 신청ID
    txb_param2 에는 구분값을 넣는데.. 
     + "1 : 발행기관신청, 팩스-발행기관신청 \n"
     + "2 : 표준코드신청, 팩스-표준코드신청 \n"
     + "3 : 팩스-다운로드IP 로 값을 넣어주세요.\n"
     */
    txb_param1.setValue(dts_detail.getCellData(1, "STD_CD_APPL_ID")); // 표준코드 신청 ID  
    txb_param2.setValue("2");
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS91100", "첨부파일", "655", "350");
};
scwin.img_pSTD_CD_GRNT_DD_SDATE_onclick = function() {
    popUpCalendar2(edt_pSTD_CD_GRNT_DD_SDATE);
};
scwin.img_pSTD_CD_GRNT_DD_EDATE_onclick = function() {
    popUpCalendar2(edt_pSTD_CD_GRNT_DD_EDATE);
};
scwin.img_pISU_DD_EDATE_onclick = function() {
    popUpCalendar2(edt_pISU_DD_EDATE);
};
scwin.img_pISU_DD_SDATE_onclick = function() {
    popUpCalendar2(edt_pISU_DD_SDATE);
};
scwin.img_COM_NM_onclick = function() {
    ins_popupOpen(txb_pISUR_CD, "", "ULDINS91300", "발행기관 코드", "700", "420");
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.img_ISU_DD_onclick = function() {
    popUpCalendar2(edt_ISU_DD);
};
scwin.grd_Grid_OnClick = function(row, colid) {
    if (row == 0) return;
    var STD_CD = dts_List.getCellData(row, "STD_CD");
    scwin.ins_detail(STD_CD);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    fn_CtrlBtn_temp("no_data");
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    scwin.cnt = rowcount;
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);
};
scwin.img_COM_NM_INFO_onclick = function() {
    txb_param1.setValue(txb_ISUR_CD.getValue()); // 발행기관코드 
    txb_param2.setValue(txb_ISUR_NM.getValue()); // 발행기관명  
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS91600", "발행기관 상세정보", "740", "835");
};
scwin.dts_detail_OnLoadCompleted = function(rowcount) {
    if (rowcount == 0) return;
    if (rowcount > 0) {
        $c.stf.setObjectValue(cmb_LIST_STAT_CD, "");
        fn_CtrlBtn_temp("update");
        var str_cfi_cd = "";
        str_cfi_cd = dts_detail.getCellData(dts_detail.rowpositon, "CFI_CD");

        //if(  str_cfi_cd != undefined && str_cfi_cd.length == "6"){ 
        //	setObjectValue(cmb_SECU_KIND_CD, str_cfi_cd.substring(5, 6)); // 4차속성 <-- CFI 4차속성 증권의 종류
        //}else{
        //	setObjectValue(cmb_SECU_KIND_CD, ""); // 4차속성 <-- CFI 4차속성 증권의 종류
        //}

        scwin.fn_set_Change(str_cfi_cd);
        if (dts_detail.getCellData(dts_detail.rowpositon, "ISUR_CD") == "") {
            $c.win.alert("외국기관 코드를 찾을 수 없습니다");
        }
        var flag = false;
        // 상장 폐지일이 있으므로 상장폐지이다.
        if (dts_detail.getCellData(dts_detail.rowpositon, "SECU_MKT_STKCERT_DELIST_DD") != "") {
            $c.stf.setObjectValue(cmb_LIST_STAT_CD, "D");
            flag = true;
        }
        var flag1 = false;
        if (flag == false) {
            //상징일 is not null 상장폐지일 null -> 상장으로 판단 2013.11.15 최진호대리님
            if (dts_detail.getCellData(dts_detail.rowpositon, "SECU_MKT_STKCERT_LIST_DD") != "" &&
                dts_detail.getCellData(dts_detail.rowpositon, "SECU_MKT_STKCERT_DELIST_DD") == "") {
                flag1 = true;
                btn_modify.setDisabled(true);
                btn_modify.src = "../img/ins/btn_modify_d.gif";
                btn_delete.setDisabled(true);
                btn_delete.src = "../img/ins/btn_delete_d.gif";
                $c.stf.setObjectValue(cmb_LIST_STAT_CD, "Y");
            } else {
                $c.stf.setObjectValue(cmb_LIST_STAT_CD, "N");
            }
        }
        if (flag1 == true) {
            //alert(" 상장종목은 수정할 수 없습니다. \n 공시총괄팀과 협의하시기 바랍니다.");

        }
    }
};
