scwin.dts_createStdCdStkInfoStdIsuNm_OnLoadCompleted = function(rowcount) {
    //alert("rowcount " +rowcount);
    /*
- 한글종목명 : 발행기관명+KDR
- 한글종목약명 : 발행기관약명+KDR
- 영문종목명 : 발행기관명(영)+KDR
- 영문종목약명 : 발행기관약명(영)+KDR 
* 주권의 기준종목명 테이블에 정보가 있는 경우 그 정보를 가져와 +이후 규칙대로.  
*/
    if (rowcount == 0) {
        $c.win.alert("해당 주권종류 코드가 존재하지 않습니다.");
        return;
    }
    var A = dts_createStdCdStkInfoStdIsuNm.getCellData(1, "A");
    var B = dts_createStdCdStkInfoStdIsuNm.getCellData(1, "B");
    var C = dts_createStdCdStkInfoStdIsuNm.getCellData(1, "C");
    var D = dts_createStdCdStkInfoStdIsuNm.getCellData(1, "D");
    var E = dts_createStdCdStkInfoStdIsuNm.getCellData(1, "E"); // 기존 주권의 보통주 존재여부

    A = $c.stf.trim(A.replace("보통주", ""));
    B = $c.stf.trim(B.replace("보통주", ""));
    C = $c.stf.trim(C.replace("보통주", ""));
    D = $c.stf.trim(D.replace("보통주", ""));
    if (E == "Y") {
        // 	주권에존재 
        txb_ISU_NM.setValue(A);
        txb_ISU_ABBRV.setValue(B);
        txb_ISU_ENG_NM.setValue(C);
        txb_ISU_ENG_ABBRV.setValue(D);
    } else {
        // 	주권에미존재 
        txb_ISU_NM.setValue(A + " KDR");
        txb_ISU_ABBRV.setValue(B + " KDR");
        txb_ISU_ENG_NM.setValue(C + " KDR");
        txb_ISU_ENG_ABBRV.setValue(D + " KDR");
    }
};
